CREATE DATABASE IF NOT EXISTS creatorhub; USE creatorhub;
DROP TABLE IF EXISTS challenge_participants; DROP TABLE IF EXISTS challenges; DROP TABLE IF EXISTS votes; DROP TABLE IF EXISTS applications; DROP TABLE IF EXISTS collaborations; DROP TABLE IF EXISTS profiles; DROP TABLE IF EXISTS students;
CREATE TABLE students(student_id INT PRIMARY KEY AUTO_INCREMENT,name VARCHAR(100) NOT NULL,email VARCHAR(150) UNIQUE NOT NULL,password_hash CHAR(64) NOT NULL);
CREATE TABLE profiles(student_id INT PRIMARY KEY,role_title VARCHAR(100),about_me TEXT,skills VARCHAR(500),work_text TEXT,FOREIGN KEY(student_id) REFERENCES students(student_id) ON DELETE CASCADE);
CREATE TABLE collaborations(collab_id INT PRIMARY KEY AUTO_INCREMENT,creator_id INT NOT NULL,title VARCHAR(150) NOT NULL,category VARCHAR(60) NOT NULL,description TEXT NOT NULL,required_role VARCHAR(100) NOT NULL,status VARCHAR(20) DEFAULT 'Open',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(creator_id) REFERENCES students(student_id) ON DELETE CASCADE);
CREATE TABLE applications(application_id INT PRIMARY KEY AUTO_INCREMENT,collab_id INT NOT NULL,applicant_id INT NOT NULL,pitch_text TEXT NOT NULL,applied_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY unique_application(collab_id,applicant_id),FOREIGN KEY(collab_id) REFERENCES collaborations(collab_id) ON DELETE CASCADE,FOREIGN KEY(applicant_id) REFERENCES students(student_id) ON DELETE CASCADE);
CREATE TABLE votes(vote_id INT PRIMARY KEY AUTO_INCREMENT,collab_id INT NOT NULL,voter_id INT NOT NULL,voted_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY unique_vote(collab_id,voter_id),FOREIGN KEY(collab_id) REFERENCES collaborations(collab_id) ON DELETE CASCADE,FOREIGN KEY(voter_id) REFERENCES students(student_id) ON DELETE CASCADE);
CREATE TABLE challenges(challenge_id INT PRIMARY KEY AUTO_INCREMENT,title VARCHAR(150) NOT NULL,category VARCHAR(60) NOT NULL,description TEXT NOT NULL,deadline DATE NOT NULL,team_size VARCHAR(40) NOT NULL,prize VARCHAR(150) NOT NULL);
CREATE TABLE challenge_participants(challenge_id INT NOT NULL,student_id INT NOT NULL,joined_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(challenge_id,student_id),FOREIGN KEY(challenge_id) REFERENCES challenges(challenge_id) ON DELETE CASCADE,FOREIGN KEY(student_id) REFERENCES students(student_id) ON DELETE CASCADE);
